function replay(source,output){
 const lines=source.split("\n"); const target=output.split("\n");
 // Restore only an unchanged heading's literal marker, at its unique exact plain-text match.
 const h=lines.map((line,i)=>({line,i,m:/^(#{1,6}) (.+)$/.exec(line)})).filter(x=>x.m);
 let restored=0;for(const {line,m} of h){
   if(target.includes(line))continue;
   const matches=target.map((s,i)=>s===m[2]?i:-1).filter(i=>i>=0);
   const sourceMatches=lines.filter(s=>s===m[2]||s===line);
   if(matches.length===1&&sourceMatches.length===1){target[matches[0]]=line;restored++;}
 }
 const candidate=target.join("\n");
 const flags=[];
 const headings=t=>t.split("\n").filter(s=>/^#{1,6} /.test(s));
 const links=t=>(t.match(/\]\([^)]+\)|https?:\/\/[^\s<>]+/gu)||[]).sort();
 const tables=t=>t.split("\n").filter(s=>/^\s*\|.*\|\s*$/.test(s));
 const code=t=>(t.match(/`[^`\n]+`/g)||[]).sort();
 const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
 if(!same(headings(source),headings(candidate)))flags.push("headings");
 if(!same(links(source),links(candidate)))flags.push("links");
 if(!same(tables(source),tables(candidate)))flags.push("tables");
 if(!same(code(source),code(candidate)))flags.push("inline_code");
 return {candidate,restored,flags};
}
